import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"旅","description":"周易集解 - 旅","frontmatter":{"title":"旅","description":"周易集解 - 旅"},"headers":[],"relativePath":"zh/classics/jijie/056.md","filePath":"zh/classics/jijie/056.md"}'),l={name:"zh/classics/jijie/056.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="旅" tabindex="-1">旅 <a class="header-anchor" href="#旅" aria-label="Permalink to “旅”">​</a></h1><h2 id="旅-1" tabindex="-1">旅 <a class="header-anchor" href="#旅-1" aria-label="Permalink to “旅”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>旅，小亨，旅貞吉。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：窮大者必失其居，故受之以旅。</p><p>崔憬曰：諺雲：作者不居，況窮大甚，而能久處乎？故必獲罪去邦，羈旅於外矣。</p><p>虞翻曰：賁初之四，否三之五，非乾坤往來也。與噬嗑之豐同義。小，謂柔得貴位而順剛。麗乎大明。故｢旅小亨，旅貞吉｣。再言旅者，謂四凶惡，進退無恆，無所容處。故再言旅，惡而愍之。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：旅小亨。柔得中乎外，而順乎剛，止而麗乎明，是以小亨旅貞吉也。旅之時義大矣哉。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>姚信曰：此本否卦。三五交易，去其本體，故曰客旅。</p><p>荀爽曰：謂陰升居五，與陽通者也。</p><p>蜀才曰：否三升五，柔得中於外，上順於剛。九五降三，降不失正，止而麗乎明。所以小亨旅貞吉也。</p><p>虞翻曰：以離日麗天，縣象著明，莫大日月，故義大也。</p><p>王弼曰：旅者，物失其所居之時也。物失所居，則咸願有附，豈非智者有為之時？故曰旅之時義大矣哉。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：山上有火，旅。君子以明慎用刑，而不留獄。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：火在山上，勢非長久，旅之象也。</p><p>虞翻曰：君子謂三。離為明，艮為慎，兌為刑，坎為獄。賁初之四，獄象不見。故以明慎用刑而不留獄。與豐折獄同義者也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，旅瑣瑣，斯其所取災。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>陸績曰：瑣瑣，小也。艮為小石。故曰旅瑣瑣也。履非其正，應離之始。離為火，艮為山，以應火，災焚自取也。故曰斯其所取災也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：旅瑣瑣，志窮災也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：瑣瑣，最蔽之貌也。失位遠應，之正介坎。坎為災眚，艮手為取，謂三動應坎。坎為志，坤稱窮，故曰志窮災也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，旅即次，懷其資，得僮僕貞。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>《九家易》曰：即，就。次，舍。資，財也。以陰居二，即就其舍，故旅即次。承陽有實，故懷其資也。初者卑賤，二得履之，故得僮僕。處和得位，正居是，故曰得僮僕貞矣。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：得僮僕貞，終無尤也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：艮為僮僕，得正承三，故得僮僕貞，而終無尤也。</p><p>案：六二履正體艮，艮為閽寺，僮僕貞之象也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，旅焚其次，喪其僮僕，貞厲。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：離為火，艮為僮僕。三動艮壞，故焚其次。坤為喪，三動艮滅入坤，故喪其僮僕。動而失正，故貞厲矣。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：旅焚其次，亦以傷矣。以旅與下，其義喪也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：三動體剝，故傷也。</p><p>虞翻曰：三變成坤。坤為下，為喪，故其義喪也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，旅於處，得其資斧，我心不快。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：巽為處。四焚棄，惡人失位遠應。故旅於處，言無所從也。離為資斧，故得其資斧。三動，四坎為心，其位未至，故我心不快也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：旅於處，未得位也。得其資斧，心未快也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>王弼曰：斧，所以斫除荊棘，以安其舍者也。雖處上體之下，不先於物；然而不得其位，不獲平坦之地者也。客子所處，不得其次，而得其資斧之地，故其心不快。</p><p>案：九四失位，而居艮上。艮為山。山非平坦之地也。四體兌巽。巽為木，兌為金，木貫於金，即資斧斫除荊棘之象者也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，射雉，一矢亡，終以譽命。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：三變坎為弓，離為矢，故射雉。五變乾體，矢動雉飛，雉象不見，故一矢亡矣。</p><p>虞翻曰：譽謂二。巽為命。五終變成乾，則二來應己，故終以譽命。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：終以譽命，上逮也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：逮，及也。謂二上及也。</p><p>乾寶曰：離為雉，為矢；巽為木，為進退；艮為手，兌為決。有木在手，進退其體，矢決於外，射之象也。一陰升乾，故曰一矢。履非基位，下又無應。雖復射雉，終亦失之。故曰一矢亡也。一矢亡者，喻有損而小也。此記祿父為王者後，雖小叛擾，終逮安周室，故曰終以譽命矣。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，鳥焚其巢，旅人先笑後號咷，喪牛於易，凶。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：離為鳥，為火；巽為木，為高。四失位變震，為筐，巢之象也。今巢象不見，故鳥焚其巢。震為笑，震在前，故先笑。應在巽，巽為號咷，巽象在後。故後號咷。</p><p>虞翻曰：謂三動時坤為牛。五動成乾，乾為易。上失三，五動應二。故喪牛於易。失位無應故凶也。五動成遯，六二｢執之用黃牛之革｣，則旅家所喪牛也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：以旅在上，其義焚也。喪牛於易，終莫之聞也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：離火焚巢，故其義焚也。</p><p>虞翻曰：坎耳入兌，故終莫之聞。</p><p>侯果曰：離為鳥，為火。巽為木，為風。鳥居木上，巢之象也。旅而贍資，物之所惡也。喪牛甚易，求之也難。雖有智者，莫之吉也。</p>',77)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
